from itertools import repeat

def f(x):
	osum = 0
	esum = 0
	while x > 0:
		d = x % 10
		if d % 2 == 0:
			esum += d
		else:
			osum += d
		x = x // 10
	return abs(osum - esum)
diamonds = list(repeat(0, 1000001))
prefix = list(repeat(0, 2000001))
for i in range(1, len(prefix)):
	prefix[i] = prefix[i - 1] + f(i)
for i in range(1, len(diamonds)):
	diamonds[i] = diamonds[i - 1] + 2 * (prefix[2 * i - 1] - prefix[i]) + f(2 * i)
t = int(input())
for _ in range(t):
	n = int(input())
	print(diamonds[n])
